+import { useEffect, useState } from 'react';
+import { describeVaultError, isVaultError, listLots, withdraw, type Lot } from './api';
+
+function messageFor(error: unknown): string {
+  return isVaultError(error) ? describeVaultError(error) : 'Unexpected error';
+}
+
+export function SeedVaultPanel(props: { step?: number }) {
+  const step = props.step ?? 10;
+  const [lots, setLots] = useState<Lot[] | null>(null);
+  const [alert, setAlert] = useState<string | null>(null);
+  const [busy, setBusy] = useState<Set<string>>(new Set());
+
+  useEffect(() => {
+    let active = true;
+    listLots()
+      .then((result) => {
+        if (active) setLots(result);
+      })
+      .catch((error: unknown) => {
+        if (active) setAlert(messageFor(error));
+      });
+    return () => {
+      active = false;
+    };
+  }, []);
+
+  async function handleWithdraw(code: string) {
+    setBusy((prev) => new Set(prev).add(code));
+    try {
+      const updated = await withdraw(code, step);
+      setLots((prev) => prev?.map((l) => (l.code === code ? updated : l)) ?? prev);
+      setAlert(null);
+    } catch (error: unknown) {
+      setAlert(messageFor(error));
+    } finally {
+      setBusy((prev) => {
+        const next = new Set(prev);
+        next.delete(code);
+        return next;
+      });
+    }
+  }
+
+  const loading = lots === null && alert === null;
+
+  return (
+    <section>
+      {loading && <p>Loading lots…</p>}
+      {alert !== null && <div role="alert">{alert}</div>}
+      {lots !== null && lots.length === 0 && <p>The vault is empty</p>}
+      {lots !== null && lots.length > 0 && (
+        <table>
+          <tbody>
+            {lots.map((lot) => (
+              <tr key={lot.code}>
+                <td>{lot.code}</td>
+                <td>{`${lot.grams} g`}</td>
+                <td>
+                  <button
+                    type="button"
+                    aria-label={`Withdraw ${step} g from ${lot.code}`}
+                    disabled={lot.grams < step || busy.has(lot.code)}
+                    onClick={() => {
+                      void handleWithdraw(lot.code);
+                    }}
+                  >
+                    {`Withdraw ${step} g`}
+                  </button>
+                </td>
+              </tr>
+            ))}
+          </tbody>
+        </table>
+      )}
+    </section>
+  );
+}
