+import { invoke } from '@tauri-apps/api/core';
+
+export interface Lot {
+  code: string;
+  grams: number;
+}
+
+export type VaultError =
+  | { kind: 'unknownLot'; code: string }
+  | { kind: 'insufficient'; code: string; available: number; requested: number }
+  | { kind: 'invalidAmount' }
+  | { kind: 'invalidCode'; code: string }
+  | { kind: 'capacityExceeded'; code: string; capacity: number };
+
+export function listLots(): Promise<Lot[]> {
+  return invoke<Lot[]>('list_lots');
+}
+
+export function withdraw(code: string, grams: number): Promise<Lot> {
+  return invoke<Lot>('withdraw', { code, grams });
+}
+
+export function deposit(code: string, grams: number): Promise<Lot> {
+  return invoke<Lot>('deposit', { code, grams });
+}
+
+function isObject(value: unknown): value is Record<string, unknown> {
+  return typeof value === 'object' && value !== null;
+}
+
+export function isVaultError(value: unknown): value is VaultError {
+  if (!isObject(value)) return false;
+  const v = value;
+  switch (v.kind) {
+    case 'unknownLot':
+    case 'invalidCode':
+      return typeof v.code === 'string';
+    case 'insufficient':
+      return (
+        typeof v.code === 'string' &&
+        typeof v.available === 'number' &&
+        typeof v.requested === 'number'
+      );
+    case 'invalidAmount':
+      return true;
+    case 'capacityExceeded':
+      return typeof v.code === 'string' && typeof v.capacity === 'number';
+    default:
+      return false;
+  }
+}
+
+export function describeVaultError(error: VaultError): string {
+  switch (error.kind) {
+    case 'unknownLot':
+      return `Lot ${error.code} does not exist`;
+    case 'insufficient':
+      return `Only ${error.available} g left in ${error.code} (requested ${error.requested} g)`;
+    case 'invalidAmount':
+      return 'Amount must be at least 1 g';
+    case 'invalidCode':
+      return `Lot code ${error.code} must look like ABC-1234`;
+    case 'capacityExceeded':
+      return `Lot ${error.code} cannot hold more than ${error.capacity} g`;
+  }
+}
