 //! Seed vault backend. See the task description for the required behaviour.

-use tauri::{Builder, Runtime};
+use std::collections::BTreeMap;
+use std::sync::Mutex;
+
+use serde::{Deserialize, Serialize};
+use tauri::{Builder, Manager, Runtime, State};
+
+const CAPACITY: u32 = 10_000;

 /// Vault contents, shared by all commands.
-pub struct SeedVault {}
+pub struct SeedVault {
+    lots: Mutex<BTreeMap<String, u32>>,
+}
+
+/// A seed lot as seen by the frontend.
+#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
+pub struct Lot {
+    pub code: String,
+    pub grams: u32,
+}
+
+/// Errors returned by the vault commands.
+#[derive(Debug, Clone, Serialize, PartialEq, Eq)]
+#[serde(tag = "kind", rename_all = "camelCase")]
+pub enum VaultError {
+    UnknownLot { code: String },
+    Insufficient { code: String, available: u32, requested: u32 },
+    InvalidAmount,
+    InvalidCode { code: String },
+    CapacityExceeded { code: String, capacity: u32 },
+}

 impl SeedVault {
     /// Creates a vault from `(lot code, grams)` pairs.
@@ -12,13 +38,85 @@ impl SeedVault {
         I: IntoIterator<Item = (S, u32)>,
         S: Into<String>,
     {
-        let _ = lots;
-        todo!("store the lots")
+        let map = lots.into_iter().map(|(c, g)| (c.into(), g)).collect();
+        SeedVault { lots: Mutex::new(map) }
+    }
+
+    fn guard(&self) -> std::sync::MutexGuard<'_, BTreeMap<String, u32>> {
+        self.lots.lock().unwrap_or_else(|e| e.into_inner())
+    }
+}
+
+fn valid_code(code: &str) -> bool {
+    let b = code.as_bytes();
+    b.len() == 8
+        && b[..3].iter().all(|c| c.is_ascii_uppercase())
+        && b[3] == b'-'
+        && b[4..].iter().all(|c| c.is_ascii_digit())
+}
+
+#[tauri::command]
+fn list_lots(vault: State<'_, SeedVault>) -> Vec<Lot> {
+    vault
+        .guard()
+        .iter()
+        .map(|(code, grams)| Lot { code: code.clone(), grams: *grams })
+        .collect()
+}
+
+#[tauri::command]
+fn withdraw(vault: State<'_, SeedVault>, code: String, grams: u32) -> Result<Lot, VaultError> {
+    if grams == 0 {
+        return Err(VaultError::InvalidAmount);
+    }
+    let mut lots = vault.guard();
+    let held = lots
+        .get_mut(&code)
+        .ok_or_else(|| VaultError::UnknownLot { code: code.clone() })?;
+    if *held < grams {
+        return Err(VaultError::Insufficient {
+            code,
+            available: *held,
+            requested: grams,
+        });
+    }
+    *held -= grams;
+    Ok(Lot { code, grams: *held })
+}
+
+#[tauri::command]
+fn deposit(vault: State<'_, SeedVault>, code: String, grams: u32) -> Result<Lot, VaultError> {
+    if grams == 0 {
+        return Err(VaultError::InvalidAmount);
+    }
+    let mut lots = vault.guard();
+    if let Some(held) = lots.get_mut(&code) {
+        let total = held.checked_add(grams).unwrap_or(u32::MAX);
+        if total > CAPACITY {
+            return Err(VaultError::CapacityExceeded {
+                code,
+                capacity: CAPACITY,
+            });
+        }
+        *held = total;
+        return Ok(Lot { code, grams: total });
+    }
+    if !valid_code(&code) {
+        return Err(VaultError::InvalidCode { code });
+    }
+    if grams > CAPACITY {
+        return Err(VaultError::CapacityExceeded {
+            code,
+            capacity: CAPACITY,
+        });
     }
+    lots.insert(code.clone(), grams);
+    Ok(Lot { code, grams })
 }

