 pub fn register<R: Runtime>(builder: Builder<R>, vault: SeedVault) -> Builder<R> {
-    let _ = vault;
     builder
+        .manage(vault)
+        .invoke_handler(tauri::generate_handler![list_lots, withdraw, deposit])
 }
